<?php
require_once __DIR__.'/../config.php';require_admin();$pageTitle='Forum moderation';
if(is_post()){verify_csrf();$id=valid_id($_POST['id']??0);$kind=$_POST['kind']??'question';$action=$_POST['action']??'';$table=$kind==='answer'?'answers':($kind==='comment'?'resource_comments':'questions');if($action==='toggle'){$pdo->prepare("UPDATE {$table} SET status=IF(status IN ('visible','visible'),'hidden','visible') WHERE id=?")->execute([$id]);set_flash('success','Content visibility updated.');}elseif($action==='delete'){$pdo->prepare("DELETE FROM {$table} WHERE id=?")->execute([$id]);set_flash('success','Content deleted.');}redirect('forum.php');}
$questions=$pdo->query("SELECT q.id,q.title,q.body,q.status,q.created_at,u.name author FROM questions q JOIN users u ON u.id=q.user_id ORDER BY q.created_at DESC LIMIT 100")->fetchAll();$answers=$pdo->query("SELECT a.id,a.body,a.status,a.created_at,u.name author,q.title question_title FROM answers a JOIN users u ON u.id=a.user_id JOIN questions q ON q.id=a.question_id ORDER BY a.created_at DESC LIMIT 100")->fetchAll();$comments=$pdo->query("SELECT rc.id,rc.body,rc.status,rc.created_at,u.name author,r.title resource_title FROM resource_comments rc JOIN users u ON u.id=rc.user_id JOIN resources r ON r.id=rc.resource_id ORDER BY rc.created_at DESC LIMIT 100")->fetchAll();require __DIR__.'/../includes/admin_header.php';?>
<section class="panel mb-2"><h2>Questions</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Question</th><th>Author</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($questions as $q): ?><tr><td><strong><?= e($q['title']) ?></strong><div class="small-muted"><?= e(excerpt($q['body'],100)) ?></div></td><td><?= e($q['author']) ?></td><td><?= badge($q['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="question"><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-outline btn-small"><?= $q['status']==='visible'?'Hide':'Show' ?></button></form> <form method="post" data-confirm="Delete this question and its answers?"><?= csrf_field() ?><input type="hidden" name="kind" value="question"><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel mb-2"><h2>Answers</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Answer</th><th>Question</th><th>Author</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($answers as $a): ?><tr><td><?= e(excerpt($a['body'],110)) ?></td><td><?= e($a['question_title']) ?></td><td><?= e($a['author']) ?></td><td><?= badge($a['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="answer"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-outline btn-small"><?= $a['status']==='visible'?'Hide':'Show' ?></button></form> <form method="post" data-confirm="Delete this answer?"><?= csrf_field() ?><input type="hidden" name="kind" value="answer"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Resource comments</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Comment</th><th>Resource</th><th>Author</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($comments as $c): ?><tr><td><?= e(excerpt($c['body'],100)) ?></td><td><?= e($c['resource_title']) ?></td><td><?= e($c['author']) ?></td><td><?= badge($c['status']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="kind" value="comment"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-outline btn-small"><?= $c['status']==='visible'?'Hide':'Show' ?></button></form> <form method="post" data-confirm="Delete this comment?"><?= csrf_field() ?><input type="hidden" name="kind" value="comment"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/admin_footer.php';?>
